"""GNCore-authored adaptive category guidance; no downloaded prose is embedded."""

# category: (discovery description, working decisions, observable validation)
GUIDES = {
    "general": ("Clarify, plan, implement, review, document, or prepare a scoped project outcome.", "Select the actual deliverable first: brief, architecture, implementation, review, tests, documentation, or release preparation. Scale planning to uncertainty and risk. Keep unresolved decisions explicit without turning routine choices into blockers.", "Trace each acceptance criterion to an artifact or observed check. Separate prepared changes from published, merged, or deployed changes."),
    "company-leadership": ("Prepare executive decisions, operating reviews, board materials, and cross-functional commitments.", "Choose the decision owner and management lens from the question. Reconcile strategic, customer, financial, operating, people, and risk evidence on a common period. Present viable options with costs, reversibility, dependencies, and a recommendation tied to the company's actual constraints.", "Tie material assertions to sources and dates. Check metric definitions and period consistency; identify an accountable owner, decision trigger, and measure for each proposed commitment."),
    "business-strategy": ("Evaluate strategy, market entry, portfolios, pricing, scenarios, and business transformation.", "Identify the decision and time horizon before building a framework. Compare alternatives using customer evidence, economics, capacity, and strategic fit. Treat scenario probabilities and market estimates as assumptions; define the least expensive useful test before a large commitment.", "Check source dates, units, denominators, sensitivities, and opportunity costs. Explain which evidence would change the recommendation."),
    "product-management": ("Discover product opportunities and turn them into requirements, experiments, roadmaps, and launch decisions.", "Start with the user problem and current workaround. Select discovery, specification, prioritization, experimentation, launch, feedback, or lifecycle work from the requested outcome. Distinguish customer observations from proposed solutions and measures of outcome from counts of shipped features.", "Link scope and acceptance cases to the problem. Check edge cases, instrumentation, accessibility, dependencies, success measures, and a decision rule for the next iteration."),
    "project-program-management": ("Plan, coordinate, recover, and close projects with explicit dependencies, capacity, and decisions.", "Establish scope, owner, milestones, dependencies, capacity, and the current baseline. Use a critical-path or dependency view when sequencing matters. For status work, explain variance and the next decision; for recovery, show what changes in scope, staffing, dates, or risk.", "Check dates, dependency order, resource conflicts, named owners, and milestone acceptance evidence. Label forecasts separately from commitments."),
    "business-operations": ("Improve operating processes, procedures, capacity, controls, quality, continuity, and automation.", "Map the actual flow of work, demand, service commitments, handoffs, and bottlenecks. Select process design, SOP, measurement, capacity, control, incident, vendor, continuity, or automation work. Improve the constraint without moving unaccounted work or risk downstream.", "Use baseline cycle time, throughput, defects, or service outcomes. Validate exceptions, recovery paths, control ownership, and how the changed process will be measured."),
    "sales-revenue": ("Research accounts, qualify opportunities, prepare sales conversations, proposals, forecasts, and renewals.", "Use the customer's context, stage definitions, stakeholder roles, and verified interaction history. Select account planning, discovery, qualification, pipeline, forecasting, proposal, negotiation, objections, territory, or renewal work. Keep drafts and proposed CRM changes distinct from completed outreach or updates.", "Verify account names, offer terms, stages, amounts, dates, and the next mutual action. Do not invent customer commitments, references, discounts, or forecast certainty."),
    "marketing-growth": ("Plan and evaluate positioning, brand, campaigns, content, acquisition, lifecycle, and marketing investment.", "Identify audience, desired action, offer, distribution channel, and evidence for the claim. Choose positioning, campaign, SEO, content, lifecycle, attribution, brand, social, budget, or launch work. Adapt tone and format to the channel while preserving the brand and factual claims.", "Check attribution windows, conversion denominators, incremental versus correlated outcomes, content accuracy, and a measurable campaign decision."),
    "finance-accounting": ("Prepare financial models, reconciliations, budgets, forecasts, close support, and variance explanations.", "Establish entity, period, currency, accounting definitions, and source of truth. Separate actuals, estimates, forecasts, and scenarios. Select budgeting, forecasting, variance, liquidity, unit economics, close, controls, investment cases, expenses, or reporting work.", "Reconcile balances and source totals; check signs, formulas, units, dates, and scenario sensitivities. Identify accounting or tax judgments requiring qualified review rather than inventing a treatment."),
    "people-human-resources": ("Support role design, hiring, onboarding, development, performance, workforce planning, and employee policies.", "Define role outcomes, job-relevant criteria, process stage, and the applicable organizational context. Use only necessary personal information and fair, consistent criteria. Distinguish observed work evidence from inference about an individual; select the requested HR artifact without making employment decisions on the user's behalf.", "Check consistency of criteria, confidentiality, accessibility, role relevance, and source-backed claims. Verify jurisdiction-sensitive requirements against current authoritative sources when needed."),
    "customer-success-support": ("Triage customer issues and prepare responses, escalations, onboarding, health reviews, and renewals.", "Identify customer impact, current status, entitlement, reproduction evidence, and ownership. Match urgency to impact and choose troubleshooting, response drafting, escalation, knowledge capture, service recovery, or success planning. Keep promises within verified product and service capabilities.", "Verify the issue and proposed resolution, preserve customer context across handoffs, and distinguish sent messages or completed changes from drafts and recommendations."),
    "legal-compliance": ("Organize legal intake, contract obligations, compliance evidence, policy gaps, and review materials.", "Identify jurisdiction, parties, purpose, dates, controlling documents, and the requested administrative or analytical deliverable. Separate quoted provisions, interpretations, risk hypotheses, and proposed wording. Preserve privilege designations and route consequential legal conclusions to a qualified reviewer.", "Cite the actual provision or authoritative rule supporting each material issue. Check version, effective date, defined terms, cross-references, and unresolved factual dependencies."),
    "procurement-vendor": ("Prepare sourcing requirements, RFPs, vendor comparisons, due diligence, negotiations, and vendor lifecycle plans.", "Define the business need, mandatory requirements, evaluation weights, total-cost horizon, and decision owner before comparing offers. Consider integration, service quality, security, exit costs, and vendor concentration alongside price.", "Apply the same criteria to every offer, verify quoted terms, show assumptions in total cost, and identify diligence gaps, contract dependencies, and exit obligations."),
    "entrepreneurship": ("Evaluate venture ideas, customer evidence, MVP scope, business models, runway, fundraising, and go-to-market choices.", "Identify the customer problem, existing alternatives, founder constraints, and the riskiest assumption. Choose the cheapest test that can change a decision. Connect the offer, distribution, costs, revenue, funding needs, and operational demands without treating a pitch narrative as evidence.", "Check runway arithmetic, unit economics, customer evidence, experiment thresholds, and what the team will stop or change if results differ from the hypothesis."),
    "software-engineering": ("Design, implement, debug, review, refactor, migrate, and release scoped software changes.", "Inspect the repository, relevant call paths, invariants, public contracts, and current tests. Choose architecture, feature work, review, debugging, refactoring, dependency, performance, migration, or release work based on the concrete task. Preserve unrelated changes and the chosen stack.", "Verify observable behavior with relevant tests, type/build checks, or reproduction steps. Cover boundary, error, and permission cases that matter to the change."),
    "data-analytics": ("Answer business questions with reproducible data audits, SQL, metrics, cohorts, experiments, forecasts, and dashboards.", "Define the question, unit of analysis, data grain, period, denominator, and decision to support. Select audit, query, visualization, metric design, cohort, experiment, forecast, insight, or data-contract work. Inspect missingness, duplication, joins, and selection effects before interpreting results.", "Reconcile totals, validate joins and filters, show uncertainty and limitations, and preserve a reproducible query or calculation path."),
    "ai-machine-learning": ("Frame, train, evaluate, improve, and monitor machine-learning or LLM systems with leakage-safe evidence.", "Define the target, intended use, data availability, metric, baseline, and compute constraints. Choose preprocessing, training, evaluation, improvement, LLM evaluation, retrieval, fine-tuning, or release monitoring. Keep training, tuning, and held-out evaluation boundaries explicit.", "Check splits, leakage, baselines, reproducibility, segment errors, uncertainty, cost, and serving constraints. Never invent a completed training or evaluation run."),
    "cybersecurity": ("Assess threats, code risks, vulnerabilities, incidents, identity, cloud controls, and security validation plans.", "Define assets, trust boundaries, adversary capabilities, exposure, and authorized scope. Use threat modeling, secure-code review, triage, incident response, identity, cloud review, controls, phishing analysis, secret response, or validation planning as the situation requires.", "Tie each finding to a reachable path, evidence, impact, and mitigation. Distinguish a scoped test from a claim that the entire system is secure."),
    "cloud-devops-sre": ("Design and operate infrastructure, delivery pipelines, containers, Kubernetes, SLOs, observability, and capacity.", "Inspect workload, topology, infrastructure definitions, service objectives, current incidents, and operating constraints. Choose architecture review, infrastructure code, CI/CD, containers, orchestration, reliability, observability, incidents, capacity, or cost work. Make rollback and ownership explicit.", "Validate configuration and a local or staging path where possible. Verify failure handling, recovery assumptions, resource estimates, and the actual deployment state."),
    "quality-engineering": ("Design risk-based test strategies, automation, end-to-end and contract checks, and release evidence.", "Map user journeys, change risk, interfaces, test environments, and current failure history. Choose test design, automation, E2E, contracts, performance, accessibility, defect triage, release gates, or flaky-test work. Select assertions from behavior rather than mirroring implementation.", "Run relevant cases with deterministic setup, preserve useful failure artifacts, and distinguish passing checks from skipped, unavailable, or unverified coverage."),
    "design-ux": ("Design and evaluate user flows, wireframes, visual systems, content, prototypes, accessibility, and handoffs.", "Identify audience, task, content hierarchy, constraints, and the existing design language. Choose research synthesis, UX review, flow, wireframe, visual direction, component system, content, prototype, accessibility, or handoff work. Use explicit style preferences and infer a suitable direction when none is supplied.", "Test representative tasks, hierarchy, readable content, keyboard operation, focus, responsive behavior, and relevant loading, empty, error, and success states."),
    "word-documents": ("Create, edit, format, review, and prepare accessible Word documents, reports, templates, forms, and redlines.", "Inspect the source document, audience, required structure, template, tracked changes, and intended output format. Preserve styles, numbering, fields, tables, headers, footers, and existing revisions when editing. Use structural styles and real document objects rather than visual spacing tricks.", "Render the document and inspect pagination, table splits, headings, images, links, and accessibility structure. Reopen the delivered file and report conversion or rendering limitations."),
    "pdf-documents": ("Extract, create, combine, split, OCR, fill, review, and verify PDF documents and redactions.", "Determine whether the PDF is text-based, scanned, tagged, form-based, or signed. Preserve originals and choose extraction, OCR, generation, merge/split, form, accessibility, review, or redaction work. Keep page coordinates, reading order, and signature effects explicit.", "Render affected pages and inspect layout. Check extracted text, form values, links, and searchability. For redaction, verify underlying text and objects are removed rather than merely covered."),
    "presentations-powerpoint": ("Create and refine presentations with a clear storyline, visual hierarchy, accurate charts, and verified layouts.", "Identify audience, decision, delivery context, source evidence, and template. Build a narrative before decorating slides. Select executive briefing, data story, visual design, editing, speaker notes, accessibility, templating, or deck QA work; keep one clear message per slide when practical.", "Render every slide and inspect overflow, contrast, typography, cropping, chart labels, numerical accuracy, speaker notes, and template consistency."),
    "spreadsheets": ("Build, audit, clean, analyze, visualize, forecast, and automate spreadsheets with correct formulas and readable models.", "Inspect workbook structure, inputs, formulas, units, dates, dependencies, and intended decisions. Separate inputs, assumptions, calculations, and outputs. Choose modeling, formula audit, cleaning, analysis, dashboard, pivot, forecasting, reconciliation, automation, or presentation work.", "Recalculate with an appropriate engine when available, reconcile totals, inspect formula errors and edge cases, and render key sheets to check labels, widths, number formats, and chart readability."),
    "research-market-intelligence": ("Investigate markets, competitors, customers, literature, surveys, and evidence with traceable sources.", "Define the question, scope, time window, decision, and evidence threshold. Prefer primary sources and separate observations from estimates and interpretations. Select source audit, literature review, market sizing, customer or competitor research, evidence mapping, survey, briefing, or monitoring work.", "Check source dates and provenance, corroborate material claims, show methodology and uncertainty, and state what the available evidence cannot establish."),
    "education-learning": ("Design objectives, lessons, curricula, assessments, study materials, tutoring, and accessible learning experiences.", "Identify the learner's starting point, learning objective, context, and available teaching material. Align explanation, practice, feedback, and assessment to the objective. Use retrieval, worked examples, scaffolding, and spaced review where they fit the task; preserve the intended cognitive demand.", "Check factual accuracy, alignment, answer keys, difficulty, accessibility, and whether the assessment actually demonstrates the target skill rather than familiarity with wording."),
    "healthcare-operations": ("Support healthcare intake, scheduling, quality, capacity, privacy, policies, audits, and administrative improvement.", "Keep the task within healthcare administration and operations. Identify service, patient-flow context, urgency, data sensitivity, staffing, and operational constraints. Use de-identified or minimum-necessary records; do not turn administrative analysis into diagnosis or treatment recommendations.", "Verify counts, dates, workflow exceptions, access boundaries, policy sources, and service impacts. Escalate clinical questions to the appropriate clinical professional rather than inferring clinical advice."),
    "ecommerce-retail": ("Improve retail catalogs, merchandising, conversion, pricing, inventory, campaigns, reviews, returns, and store operations.", "Inspect the actual catalog, customer journey, stock position, margins, fulfillment, and channel constraints. Choose content, merchandising, conversion, pricing, demand, promotion, reviews, returns, operations, or storefront QA. Preserve real product attributes and customer terms.", "Validate prices, stock and variant behavior, shipping and return claims, checkout states, campaign arithmetic, and measured outcomes without inventing scarcity or customer endorsements."),
    "business-communications": ("Draft and edit executive briefs, emails, updates, policies, reports, crisis messages, and localized business content.", "Identify audience, purpose, action, source facts, tone, channel, and sensitivity. Choose structure and level of detail around the reader's decision. Preserve the writer's intent, distinguish facts from proposals, and keep distribution separate from drafting.", "Verify names, dates, figures, commitments, links, terminology, and tone. Ensure the requested action and owner are clear and translations preserve meaning."),
    "supply-chain-logistics": ("Plan demand, sourcing, suppliers, inventory, warehouses, transport, resilience, and supply-chain performance.", "Establish SKU or shipment grain, planning horizon, demand variability, lead times, service targets, constraints, and cost basis. Trace dependencies across suppliers, inventory, warehouses, transport, and customers. Optimize the end-to-end outcome rather than one isolated metric.", "Check units, calendars, stock balances, lead-time assumptions, service-cost tradeoffs, capacity, and disruption scenarios. Separate forecast demand from confirmed orders."),
    "web-frontend": ("Build or redesign a complete web interface, automatically choosing an appropriate visual direction unless the user specifies one.", "Inspect the app and product brief, then choose a coherent visual direction, content hierarchy, component system, density, and motion budget. Honor explicit themes and the existing brand. When the user gives only an idea, infer a suitable direction and proceed with a concise rationale.", "Verify the key user journey, responsive layouts, real content, keyboard operation, focus, form errors, state transitions, and loading behavior. Inspect browser screenshots where tools are available and report actual build and test evidence."),
    "backend-engineering": ("Build and improve backend services, APIs, persistence, integrations, AI systems, delivery, and observability in the selected stack.", "Follow the request from validation and authentication through domain rules, transactions, external calls, background work, and telemetry. Select the actual framework and relevant specialist modes. Define contracts, ownership, failure semantics, retry boundaries, and operational constraints.", "Verify success, invalid input, denied access, relevant concurrency or idempotency cases, and failure recovery. Use measured evidence for performance claims and distinguish local checks from deployed outcomes."),
    "code-engineering": ("Build, investigate, review, test, refactor, and verify software across languages using task-appropriate workflows.", "Choose a workflow from the requested outcome and uncertainty. Reuse the repository's conventions, inspect relevant call paths, and preserve public contracts and user changes. Use diagnosis before speculative fixes, contracts before cross-service changes, and meaningful tests for behavior that can regress.", "Run the relevant build, type, test, lint, analysis, or reproduction checks. Keep review findings evidence-based and fix causes without weakening assertions. Additional agents are optional and require support and authorization."),
    "machine-learning": ("Develop reproducible machine-learning workflows from data preparation and training to evaluation, optimization, and serving.", "Identify target, data grain, split strategy, baseline, framework, hardware, and compute budget. Fit transforms on training data, preserve held-out evaluation, and control experiments with explicit configuration and data versions. Use error analysis to choose the next experiment.", "Check leakage, tensor or schema contracts, class imbalance, metric choice, baseline comparisons, reproducibility, segment errors, and serving cost. State runs not executed and metrics not measured."),
    "ai-engineering": ("Build and evaluate LLM applications, retrieval systems, prompts, and model-assisted user workflows.", "Define the useful task, trusted inputs, retrieval sources, tool boundaries, latency and spending limits, and failure handling. Use representative positive, negative, adversarial, and ambiguous cases. Separate source evidence from model-generated claims and bound tool retries and external actions.", "Evaluate task success, retrieval relevance, groundedness, permissions, failure recovery, latency, and cost against a baseline. Do not infer correctness from fluent output alone."),
    "analytics": ("Define and evaluate product analytics, instrumentation, funnels, retention, and decision metrics.", "Start with the decision and user behavior to measure. Specify events, entities, properties, time windows, eligibility, identity rules, and denominators. Inspect instrumentation before interpreting changes and distinguish acquisition, activation, engagement, retention, and revenue questions.", "Check event completeness, duplicate or delayed events, cohort definitions, tracking changes, selection bias, and whether a metric can be gamed."),
    "automation": ("Design and implement reliable automations with explicit inputs, state, retries, ownership, and recovery.", "Map the existing manual workflow and choose a useful bounded automation. Define triggers, permissions, idempotency, error handling, rate limits, and human intervention points based on actual risk. Use supported tools and preserve the requested notification behavior.", "Test normal, duplicate, delayed, partial-failure, and recovery cases. Verify that retries cannot repeat consequential side effects and that useful failures reach the right owner."),
    "cloud": ("Evaluate cloud architecture and cost choices against workload, reliability, security, and operational constraints.", "Inspect the actual provider, workload, data sensitivity, traffic shape, recovery objectives, team capacity, and budget. Compare managed and self-managed options by total operating burden, failure modes, scale, portability, and cost assumptions.", "Validate architecture assumptions, trust boundaries, capacity estimates, recovery plans, and cost sensitivity. Mark estimates and avoid claiming compliance or deployed readiness without evidence."),
    "content": ("Plan, adapt, translate, and maintain content around audience needs, factual accuracy, and channel constraints.", "Identify audience, purpose, desired action, brand voice, source material, and content lifecycle. Preserve meaning and approved terminology while adapting structure, depth, language, and distribution format. Treat localization as a context-sensitive adaptation rather than literal substitution.", "Check facts, claims, links, tone, readability, terminology, and culturally dependent examples. Separate drafts from published content."),
    "data": ("Inspect, transform, analyze, and move data through reproducible pipelines with explicit contracts.", "Identify the question, source schema, data grain, keys, units, missingness, and downstream consumers. Preserve raw inputs and define deterministic transformations, validation, lineage, scheduling, and recovery around the actual workload.", "Check row counts, key uniqueness, schema drift, missing values, reconciliation, incremental behavior, and replay safety. Keep queries and transformations reproducible."),
    "data-engineering": ("Design databases, data pipelines, and governance with explicit schemas, ownership, lineage, and quality controls.", "Inspect access patterns, data contracts, change rate, consistency needs, sensitivity, retention, and operational scale. Choose schema, ingestion, transformations, orchestration, or governance controls to fit the actual consumers and recovery requirements.", "Verify constraints, migrations, data-quality rules, lineage, access controls, retention behavior, and backfill or replay safety with representative inputs."),
    "data-science": ("Clean and analyze data with reproducible SQL, statistics, experiments, visualizations, and spatial methods.", "Define the unit of analysis, hypothesis or question, population, period, and decision. Inspect missingness, selection, duplicates, distributions, and measurement definitions. Choose descriptive, inferential, experimental, predictive, or spatial methods appropriate to the data.", "Show denominators, uncertainty, assumptions, sensitivity, and limitations. Separate association from causation and use comparable groups or explicit identification assumptions for causal claims."),
    "design": ("Conduct UX research and build design systems around real tasks, semantic tokens, components, and accessible interaction.", "Choose research or system design from the requested deliverable. Ground decisions in user tasks and existing product constraints. For research, define questions, participants, and evidence limits; for systems, connect primitive tokens to semantic roles and component state contracts.", "Check evidence quality, consistency, keyboard and assistive-technology behavior, themes, content edge cases, and whether a component can be used predictably by its callers."),
    "developer-tools": ("Design and improve command-line interfaces with predictable commands, output, exit codes, and safe file behavior.", "Inspect current CLI conventions, scripts, callers, and platform support. Define argument grammar, help, stdout/stderr behavior, machine-readable output, exit codes, and mutation boundaries. Keep commands composable and avoid hidden state or implicit destructive behavior.", "Test representative success, invalid input, missing files, paths with spaces, duplicate selections, and error output. Verify actual written paths and cross-platform assumptions."),
    "devops": ("Improve delivery workflows and Kubernetes operations with reproducible configuration, observability, and recovery.", "Inspect pipelines, environment boundaries, container definitions, cluster resources, secrets handling, and rollout practices. Prefer a scoped improvement that reduces an observed failure or feedback delay. Make readiness, resource, dependency, and rollback assumptions explicit.", "Validate manifests and the relevant build or staging path. Check configuration drift, failure signals, rollout and rollback behavior, and secret exposure."),
    "documentation": ("Write and maintain technical and API documentation from verified behavior, examples, and audience needs.", "Identify reader, task, source of truth, supported versions, and the action the documentation should enable. Trace examples to actual APIs and command behavior. Use a clear progression from purpose and setup to a working example, constraints, and troubleshooting.", "Run examples where practical, validate links and symbols, check argument and response shapes, and distinguish documented guarantees from implementation details."),
    "education": ("Create accurate, accessible learning content with clear objectives, examples, practice, and feedback.", "Determine the learner's level, prior knowledge, target capability, and learning context. Break the explanation into meaningful steps and use examples that expose the underlying concept. Include practice and feedback that demonstrate transfer rather than memorization.", "Check facts, answer keys, prerequisite assumptions, clarity, accessibility, and alignment between objectives, activities, and assessment."),
    "game-development": ("Build and improve game mechanics, interactions, state, assets, and performance in the existing engine.", "Inspect the engine, platform, input model, scene or entity structure, asset pipeline, and target player experience. Implement a small complete gameplay loop, define state transitions and reset behavior, and keep frame work separate from slower loading or UI operations.", "Play the main loop and test input, pause/resume, win/loss, restart, edge collisions, resource cleanup, and target-device performance. Do not claim playtesting without running it."),
    "mobile-development": ("Build mobile application flows with platform-appropriate navigation, state, permissions, accessibility, and lifecycle handling.", "Inspect the target platform, framework, navigation patterns, data flow, and device constraints. Choose native conventions where they improve familiarity. Handle offline or unreliable networking, permission denial, background/foreground transitions, keyboard insets, and touch interaction.", "Verify the key flow at relevant device sizes, accessibility settings, lifecycle states, and error cases. Report simulator, device, and platform checks separately."),
    "operations": ("Investigate operational incidents and coordinate containment, recovery, communication, and follow-up from evidence.", "Establish impact, timeline, current state, known changes, ownership, and authorized response scope. Separate observations from hypotheses and choose reversible containment while investigating the cause. Maintain a clear incident record and recovery criterion.", "Verify restoration with service evidence rather than a successful command alone. Record remaining exposure, customer impact, follow-up owners, and checks not yet completed."),
    "product": ("Investigate user problems and validate product opportunities before committing to a solution.", "Identify target users, current behavior, pain, alternatives, business constraints, and the decision to make. Choose interviews, existing evidence, behavioral analysis, prototype tests, or a limited experiment based on the riskiest assumption.", "Separate observed evidence from stated preferences and inferred demand. Define a threshold for proceeding, changing direction, or stopping."),
    "professional-services": ("Prepare contract-review and financial-analysis support with traceable sources, assumptions, and review boundaries.", "Identify the requested deliverable, relevant jurisdiction or accounting context, source documents, dates, parties, and intended decision. Separate extraction, calculation, interpretation, and advice. Preserve confidential information and surface gaps that require a qualified specialist.", "Verify provisions or figures against source material, reconcile calculations, check dates and definitions, and label uncertainty and limitations explicitly."),
    "python": ("Build, profile, package, and migrate Python libraries while preserving public APIs and supported runtimes.", "Inspect Python versions, package layout, public interfaces, dependency policy, and tests. Choose library design, performance work, packaging, or migration based on the task. Use idiomatic types and resource handling; profile before optimizing and verify artifacts rather than only source imports.", "Run relevant tests and build/type checks. Inspect wheel and source distributions, import from a clean installation, and verify supported-version assumptions."),
    "quality-assurance": ("Audit accessibility and performance, plan tests, and connect requirements to verifiable acceptance evidence.", "Identify the requested audit or validation scope, supported environments, baseline, and acceptance criteria. Use measurable checks and representative user tasks. Distinguish an accessibility, performance, or test-strategy review from a whole-product certification.", "Record commands, environments, observed outcomes, reproducible failures, and unperformed manual checks. Compare performance under the same conditions and tie findings to concrete behavior."),
    "release-engineering": ("Prepare a software release with consistent versions, tested artifacts, migration notes, and a reviewable delivery plan.", "Inspect the release process, pending changes, package metadata, supported runtimes, CI, credentials requirements, and rollback path. Synchronize versions and release notes, build artifacts, and verify a clean installation. Use the user's chosen release scope and destination.", "Check the artifact contents, tests, metadata, migration compatibility, and remote state. Distinguish committed, pushed, tagged, uploaded, and publicly verified states."),
    "research": ("Synthesize evidence into a clear answer with source provenance, uncertainty, and decision-relevant conclusions.", "Define the research question, inclusion scope, dates, and evidence standard. Prefer primary sources and compare claims across independent evidence. Separate source facts, interpretation, estimates, and recommendations; preserve disagreements rather than smoothing them away.", "Verify citations and source dates, check that each material claim is supported, and state missing evidence, methodological limits, and what would change the conclusion."),
    "security": ("Review web security and privacy boundaries using concrete code paths, data flows, and source-backed requirements.", "Map sensitive data, identity, access control, trust boundaries, and external exposure. Inspect relevant authentication, input, query, output, session, logging, retention, and consent behavior. Choose review depth based on the requested change and actual risk.", "Reproduce relevant issues locally when practical, verify allowed and denied cases, and distinguish observed vulnerabilities or privacy gaps from hypothetical concerns."),
    "testing": ("Design and run unit, integration, end-to-end, automation, and performance tests for important software behavior.", "Choose the test layer that can observe the requirement with the least unnecessary setup. Use representative fixtures, clear contracts, deterministic isolation, and behavior-based assertions. Include relevant boundaries, errors, permissions, concurrency, or recovery rather than aiming for a fixed test count.", "Demonstrate useful failures where appropriate, run focused regressions after fixes, and preserve failure evidence. Do not hide flaky behavior, weaken assertions, or claim checks that were not run."),
    "web-development": ("Build scoped web features and improve technical SEO using the repository's existing frontend and backend stack.", "Trace the requested user flow through pages, APIs, data, and deployment constraints. Preserve local architecture and public behavior. For SEO work, inspect crawlable rendered content, metadata, canonical URLs, sitemap, redirects, and relevant structured data.", "Verify the user journey, error and permission states, responsive behavior, rendered HTML, and applicable build or test checks. Separate technical discoverability improvements from search-ranking predictions."),
}

CANONICAL_IDS = {"backend-engineering": "web-backend", "code-engineering": "code-build"}
